package bg.tuvarna.sit.project.ps.internshipmanagement.service;
import bg.tuvarna.sit.project.ps.internshipmanagement.dto.*;import bg.tuvarna.sit.project.ps.internshipmanagement.dto.profile.*;import bg.tuvarna.sit.project.ps.internshipmanagement.entity.*;import bg.tuvarna.sit.project.ps.internshipmanagement.exception.*;import bg.tuvarna.sit.project.ps.internshipmanagement.mapper.StudentProfileMapper;import bg.tuvarna.sit.project.ps.internshipmanagement.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class StudentProfileService{private final StudentProfileRepository profiles;private final CurrentUserService current;private final StudentProfileMapper mapper;public StudentProfileService(StudentProfileRepository p,CurrentUserService c,StudentProfileMapper m){profiles=p;current=c;mapper=m;}public StudentProfileDto get(){return mapper.toDto(profile());}@Transactional public StudentProfileDto update(StudentProfileUpdateRequest r){StudentProfile p=profile();if(!p.getFacultyNumber().equals(r.getFacultyNumber())&&profiles.existsByFacultyNumber(r.getFacultyNumber()))throw new DuplicateResourceException("Faculty number is already used");User u=current.get();u.setFirstName(r.getFirstName());u.setLastName(r.getLastName());p.setFacultyNumber(r.getFacultyNumber());p.setSpecialty(r.getSpecialty());p.setCourse(r.getCourse());p.setSkills(r.getSkills());return mapper.toDto(profiles.save(p));}private StudentProfile profile(){return profiles.findByUserId(current.get().getId()).orElseThrow(()->new ResourceNotFoundException("Student profile not found"));}}
